Here is the commit message:
Fix leading WS on opening code fences

This fixes an error that was introduced in 913c28d.

Here is the root cause:
The bug was caused by an incorrect handling of leading whitespace on opening code fences, where the code was relying on a previously counted whitespace variable instead of directly checking for spaces in the data. This led to improper parsing of fenced code blocks, resulting in errors when processing code with leading whitespace.

Here is the patch:
  */
 static size_t parse_fenced_code_block(uint8_t *data, CodeBlk *blk, size_t i)
 {
-    String *cb = init_string(BLK_BUF);
-    size_t ws  = 0;
+    String *cb  = init_string(BLK_BUF);
     ssize_t cfl = 0;    /* Closing-fence line length (in bytes). */

     /* Parse every line as part of this code block 
      * until we find the closing fence. */
     while (true) {
-        ws = count_indentation(data);

         /* Check this line for a code fence. */
         if ((cfl = is_closing_code_fence(data, blk)) > 0) break;
         else cfl = 0;

         /* Advance past the WS on the opening code fence. */
         size_t linews = 0;
-        while (blk->ws > 0 && ws > 0 && linews < blk->ws) {
+        while (blk->ws > 0 && *data == 0x20 && linews < blk->ws) {
             data++, i++;
             linews++;
         }

         /* Add characters until we reach a newline. */
         while (*data && *data != '\n') {
             if (cb->length < cb->allocd - NEWLINE - NULL_CHAR) {
                 *cb->data++ = *data++;
                 cb->length++;
                 i++;
             }
             else realloc_string(cb, cb->allocd + BLK_BUF);
         }

         /* Add the newline. */
         *cb->data++ = '\n';
         cb->length++;

         if (!(*data)) break;
         i++, data++;
     }

     *cb->data = '\0';
     cb->data -= cb->length;
     add_markdown(cb, FENCED_CODE_BLOCK, blk);
     return i + cfl;
 }



